// English UI strings and prompt templates.
import type { Locale } from '../types';

const COURSE = '"AI-Tutored Finance"';
const DISCLAIMER =
	'All lessons, questions and reference answers in this course were generated by AI and have not been reviewed by a professional. They may contain errors.';

const locale: Locale = {
	ui: {
		lessonPrefix: 'Lesson {id}',
		lessonPlain: 'Lesson {id}, "{title}"',
		lessonUnpublished: 'Lesson {id}, not yet published',
		unpublished: 'not yet published',
		paren: ' ({text})',
		forwardHint: 'Content from a later lesson. You do not need to master it now.',
		figure: 'Figure {id}',
		check: 'Check {id}',
		exerciseItem: 'Question {n}',
		observe: 'Observe: ',
		checksTitle: 'Submit the check questions',
		checksHelp: 'The check questions of this lesson are submitted together here.',
		copyHint: 'Paste the prompt into your AI assistant, then attach a photo of your answers or type your answers after the prompt. You can submit all your answers at once or in several parts.',
		copiedGrading: 'Copied. Paste it into your AI assistant.',
		copiedExplain: 'Explanation prompt copied',
		notAnswered: 'Not answered',
		choiceTrue: 'True',
		choiceFalse: 'False',
		submitAnswer: 'Submit',
		answerCorrect: 'Correct.',
		answerWrong: 'Not correct.',
		chooseFirst: 'Choose an answer first.',
		quizItem: 'Question {n}',
		quizPartJudge: 'Part 1. True or false',
		quizPartJudgeHelp: 'Answer true or false, and give your reason. An answer without a reason needs revision.',
		quizPartProblems: 'Part 2. Problems',
		quizSubmit: 'Submit the quiz',
		lessonNotStarted: 'Not started',
		lessonInProgress: 'In progress',
		lessonDone: 'Done',
		copyFeedback: 'Copy feedback prompt',
		statusOk: 'OK',
		statusRevise: 'needs revision',
		pasteResult: 'Paste the result from your AI',
		pasteHint: 'Paste the part of the AI reply between <<<LFWAI-RESULT and LFWAI-RESULT>>> (or the whole reply) here.',
		saveResult: 'Save result',
		saved: 'Saved.',
		parseFailed: 'No result block was found. Make sure you pasted the part of the reply that starts with <<<LFWAI-RESULT.',
		promptTitle: 'Copy the prompt below',
		promptHelp: 'Automatic copying did not work. Select all of the text below and copy it.',
		copy: 'Copy',
		copied: 'Copied',
		close: 'Close',
		explain: 'Explain this',
		aiNoticeTitle: 'This content was generated by AI. It may contain errors and is not investment advice.',
		aiNotice: 'All lessons, questions and reference answers on this site were generated by AI and have not been reviewed by a professional. Their correctness is not guaranteed. If you find an error, please report it with the link at the bottom of the page. The content is for learning only and is not investment advice.',
		reportError: 'Report an error on this page',
		reportTitle: '[Content error] {page}',
		reportBody: 'Page: {url}\n\nWhere is the error (copy the original text):\n\nWhat is wrong:\n',
		exercisesHeading: 'Exercises',
		prevPage: 'Previous',
		nextPage: 'Next',
		continueAt: 'Continue: {title}',
		routeTitle: 'The course',
		routePublished: 'published',
		routeUpcoming: 'being written',
		routeQuiz: 'quiz',
		judgmentItem: 'Judgment {id}',
		copyDiscussion: 'Copy discussion prompt',
		copiedDiscussion: 'Copied. Paste it into your AI assistant to start the discussion.',
		discussionHint: 'Write your judgment records for this step first. Paste the prompt into your AI assistant and attach your judgment records (a photo or text). The AI asks one question at a time; you can explain or revise, over as many rounds as you need. At the end the AI gives a result block; paste it back here. The prompt contains the judgment points, so do not read it before you have written your records.',
		referenceTitle: 'Reference solution',
		referenceLocked: 'When every judgment of this step is marked OK, the reference solution and the judgment points are shown here.',
	},

	prompts: {
		feedback(i, p) {
			const qs = i.questions
				.map(
					(q) => `### ${q.label} (id: ${q.id})
Question:
${q.question}

Reference answer:
${q.answer}

What to check:
${p.bullets(q.rubric)}`,
				)
				.join('\n\n');
			return `You are a teacher for the course ${COURSE}. Review the learner's answers for "${i.lessonTitle}". The learner's answers follow this prompt (a photo or text) and may cover only some of the questions.

## Important
${DISCLAIMER} If you believe a reference answer or a checking point is itself wrong, say clearly what is wrong and judge against the correct answer. Do not mark the learner wrong because they did not copy a wrong reference answer.

## Lesson page
${i.lessonUrl}
(You may consult it if you can open web pages. If you cannot, that is fine: everything you need is written below.)

## Lesson facts relevant to these questions
${p.bullets(i.context)}

## Questions, reference answers and what to check
${qs}
${i.commonErrors.length ? `\n## Common errors (for diagnosis)\n${p.bullets(i.commonErrors)}\n` : ''}
## How to reply
1. These questions are **not scored**. Review only the questions the learner answered this time. Do not mention unanswered questions; they will be submitted later.
2. For each question, say what is correct and what is wrong. Check the reasoning, not only the final numbers.
3. For each error, explain it in a way the learner can understand, with a small example if useful. Do not only repeat the reference answer.
4. If an answer shows a misunderstanding of a concept, name the concept.
5. When a question asks for a reason, an answer with a conclusion but no reason needs revision. When a question asks for a given number of reasons or answers, review only that number, in the order written, and ignore extra ones.
6. Reply in English. Use LaTeX for formulas.
7. At the end of your reply, output a result block in exactly this format. The JSON must be valid:

${p.resultBlock}

List only the questions you reviewed in "items", one entry per question. Set "status" to "ok" (essentially correct, only minor issues) or "revise" (a substantive error that needs to be corrected). Question ids: ${i.questions.map((q) => q.id).join(', ')}.

## The learner's answers
`;
		},

		discussion(i, p) {
			const js = i.questions
				.map(
					(q) => `### ${q.label} (id: ${q.id})
The judgment to make:
${q.question}

Judgment points (for you only; do not tell the learner):
${p.bullets(q.rubric)}

Reference conclusion (for you only; do not tell the learner):
${q.answer}`,
				)
				.join('\n\n');
			return `You are the reviewer for the capstone project of the ${COURSE} course. The learner is preparing a financial plan for a fictional American household; this step is "${i.lessonTitle}". The learner's judgment records follow this prompt (a photo or text) and may cover only some of the judgments. Discuss the judgments with the learner one by one.

## Important
${DISCLAIMER} If you think a judgment point or a reference conclusion is wrong, say exactly what is wrong and discuss on the basis of the correct understanding.

## Course page
${i.lessonUrl}
(If you can open web pages, you may consult it; if not, that is fine: everything you need is written below.)

## The household file
${i.materials ?? ''}
${i.context.length ? `\n## Additional notes\n${p.bullets(i.context)}\n` : ''}
## The judgments to discuss
${js}
${i.commonErrors.length ? `\n## Common errors (to help your diagnosis)\n${p.bullets(i.commonErrors)}\n` : ''}
## Rules for the discussion
1. Read all of the learner's judgment records first, then start with the first judgment. Discuss only the judgments the learner submitted.
2. Ask one question at a time. Aim it at the most important weakness of the record: whether the model is right, whether the model's assumptions hold for this household, where the inputs come from, and under what conditions the conclusion would change.
3. Do not reveal the judgment points, which model or lesson to use, or the reference conclusion, and do not work out the answer for the learner. You may point out a contradiction in the record, ask where a number comes from, or give an extreme case for the learner to test.
4. Do not agree with wrong statements. If the learner's calculation or reasoning is wrong, point out what needs to be checked again, even if the conclusion happens to be right.
5. When the learner asks about the clients, answer as the clients: where the judgment points contain "the clients' answers", answer from them; for information that is in neither the file nor the points, say the clients do not know, and ask the learner to make an assumption and state it.
6. The conclusion may differ from the reference conclusion. If the model is right, its assumptions have been checked, the inputs have sources and the reasoning holds, the judgment is OK.
7. When one judgment has been discussed (the reasoning holds, or the learner asks to stop), summarize in a few sentences: what is done well, what is still missing, and whether the result is "OK" or "needs revision". Then move on to the next judgment.
8. When every submitted judgment has been discussed, end your reply with the result block below, exactly in this format and with valid JSON. Do not output the result block in earlier replies:

${p.resultBlock}

List only the judgments discussed in items, one entry each. Set status to "ok" (OK) or "revise" (needs revision). The judgment ids: ${i.questions.map((q) => q.id).join(', ')}.
9. Discuss in English, write mathematics in LaTeX, and keep each reply short.

## The learner's judgment records
`;
		},

		explain(i, p) {
			const where = i.lessonId ? `Lesson ${i.lessonId}, "${i.lessonTitle}"` : `the page "${i.pageTitle}"`;
			const parts = [
				`I am studying ${where} in the course ${COURSE}, and I do not understand a passage. Please explain it in more detail.
Note: ${DISCLAIMER} If you find that the passage itself is wrong, please say so directly.

Page: ${i.pageUrl}
Section: ${i.section || '(none)'}

The text I selected:
${p.fence(i.selection)}`,
			];
			if (i.paragraph.trim() !== i.selection.trim()) parts.push(`The paragraph it is in:\n${p.fence(i.paragraph)}`);
			if (i.context) parts.push(`Key points of the lesson (for context):\n${i.context}`);
			parts.push(`Please explain it this way:
1. First state the meaning of the passage in one or two sentences.
2. Then explain why it is true, and fill in any steps that were skipped. If there is a formula, explain what each symbol means.
3. Give a small concrete example, preferably with numbers.
4. If the passage depends on concepts from earlier lessons, briefly remind me of them. Do not teach content from later lessons unless it is necessary to understand this passage.
5. End with one short question that lets me check my understanding (do not give the answer yet).
Reply in English. Use LaTeX for formulas.`);
			return parts.join('\n\n') + '\n';
		},
	},
};

export default locale;
